	package utb.fai;



	import java.util.HashSet;
	import java.util.LinkedList;
	import java.util.ArrayList;
	import java.util.Map;
	import java.util.concurrent.ExecutorService;
	import java.util.concurrent.Executors;
	import java.util.Set;
	import java.util.concurrent.ConcurrentHashMap;
	import java.util.Queue;
	import java.util.concurrent.ConcurrentLinkedQueue;
	import java.util.concurrent.atomic.AtomicInteger;

	import java.net.URI;
	import java.net.http.HttpClient;
	import java.net.http.HttpRequest;
	import java.net.http.HttpResponse;

	import java.io.ByteArrayInputStream;

	import org.jsoup.Jsoup;
	import org.jsoup.nodes.Document;



	public class App {

		public static void main(String[] args) {
			Queue<URIinfo> foundURIs = new ConcurrentLinkedQueue<>();
			Set<URI> visitedURIs = ConcurrentHashMap.newKeySet();
			URI uri;
			try {

				if (args.length < 1) {
					System.err.println("Missing parameter - start URL");
					return;
				}

				HttpClient client = HttpClient.newBuilder()
					.followRedirects(HttpClient.Redirect.NORMAL)
					.build();

				ExecutorService executor = Executors.newFixedThreadPool(4);

				uri = new URI(args[0]);
				foundURIs.add(new URIinfo(uri, 0));
				visitedURIs.add(uri);

				/**
				 * Zde zpracujte dalí parametry - maxDepth a debugLevel
				 */

				int maxDepth = 2;
				int debugLevel = 0;

				if (args.length >= 2) {
					maxDepth = Integer.parseInt(args[1]);
				}

				if (args.length >= 3) {
					debugLevel = Integer.parseInt(args[2]);
				}


				ConcurrentHashMap<String, Integer> wordCounts = new ConcurrentHashMap<>();
				AtomicInteger activeTasks = new AtomicInteger(0);


				while (!foundURIs.isEmpty() || activeTasks.get() > 0) {
					URIinfo URIinfo = foundURIs.poll();
					if (URIinfo == null) { continue; }

					ParserCallback callBack = new ParserCallback(
						visitedURIs, foundURIs, maxDepth, debugLevel,
						URIinfo.uri, URIinfo.depth, wordCounts);

					activeTasks.incrementAndGet();
					executor.submit(() -> {
						try {
							URI pageURI = URIinfo.uri;
							System.err.println("Analyzing " + pageURI);

							HttpRequest request = HttpRequest.newBuilder()
								.uri(pageURI)
								.build();

							HttpResponse<byte[]> response =
								client.send(request, HttpResponse.BodyHandlers.ofByteArray());

							if (response.statusCode() == 200) {
								byte[] html = response.body();

								String contentType = response.headers()
									.firstValue("Content-Type")
									.orElse("");

								String charset = null;

								for (String part : contentType.split(";")) {
									part = part.trim();

									if (part.toLowerCase().startsWith("charset=")) {
										charset = part.substring("charset=".length()).trim();
										break;
									}
								}

								if (html != null) {
									Document doc = Jsoup.parse(
										new ByteArrayInputStream(html),
										charset,
										pageURI.toString()
									);

									callBack.parseDocument(doc);

									System.out.println("Title: " + doc.title());
								}
							} 
						} catch (Exception e) {
							System.err.println("Error processing " + URIinfo.uri + " :");
							e.printStackTrace();
						} finally {
							activeTasks.decrementAndGet();
						}
					});
				}
				executor.shutdown();
				executor.awaitTermination(1, java.util.concurrent.TimeUnit.MINUTES);

				ArrayList<Map.Entry<String, Integer>> sortedWords = new ArrayList<>(wordCounts.entrySet());
				sortedWords.sort(
					(a, b) -> b.getValue().compareTo(a.getValue())
				);

				for (int i = 0; i < Math.min(20, sortedWords.size()); i++) {
					Map.Entry<String, Integer> entry = sortedWords.get(i);
					System.out.println(entry.getKey() + ";" + entry.getValue());
				}

			} catch (Exception e) {
				System.err.println("Unhandled error occured...");
				e.printStackTrace();
			}
		}

	}
